using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Threading.Tasks;
internal sealed partial class ControlWindow {
 internal async Task RunNameSmoke(string mode){try{
  if(mode=="restart"){
   var x=library.Doc.Items.Single(i=>i.ResourceId=="394944");Require(x.Name=="咒术五条悟"&&x.NameSource!=null&&x.NameSource.Id=="394944"&&x.PreviewConfirmedSha256==null,"Name lost on restart");SelectWallpaper(x);ClientShot(this,"name-import-restart");Common.SaveNew(Path.Combine(Common.Root,"evidence/name-restart-passed.json"),new{item=x,cacheRequiredForImportedName=false,noPlayer=CurrentRun==null});Close();return;
  }
  OpenLocalImport();await WaitCoverDialog();var data=Common.Read(Path.Combine(importOperation.Folder,"result.json"));var found=CoverCandidates(data);var target=found.Single(x=>x.Id=="394944");Require(target.Name=="咒术五条悟"&&target.NameSource!=null&&target.NameSource.Id==target.Id,"Real official name not mapped");Require(found.Single(x=>x.Id=="317495").Name=="雨中静默少女","Known existing name mismatch");
  foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id==target.Id){row.Selected=true;row.EnsureVisible();break;}await Task.Delay(150);ClientShot(importDialog,"official-name-candidate");Common.SaveNew(Path.Combine(Common.Root,"evidence/name-first-scan.json"),data);await importDialog.Scan();Require(CoverCandidates(Common.Read(Path.Combine(importOperation.Folder,"result.json"))).Single(x=>x.Id==target.Id).Name==target.Name,"Refresh lost name");
  importDialog.Close();Require(library.Doc.Items.Count==4&&CurrentRun==null,"No autoimport or playback");ClientShot(this,"name-four-card-home");
  // Existing placeholders update while meaningful/custom names and version suffixes remain intact.
  var placeholder=new WallpaperItem{Id="fixture-existing",Name="本地壁纸 394944",RegisteredSha256=target.CoverSourceSha256,ResourceId=target.Id};Require(UpdateOfficialName(placeholder,target)&&placeholder.Name==target.Name&&placeholder.NameSource!=null,"Existing placeholder not updated");
  var custom=new WallpaperItem{Id="fixture-custom",Name="我的五条悟",RegisteredSha256=target.CoverSourceSha256,ResourceId=target.Id};Require(!UpdateOfficialName(custom,target)&&custom.Name=="我的五条悟","Custom name overwritten");
  var version=new WallpaperItem{Id="fixture-version",Name="本地壁纸 394944 · "+target.CoverSourceSha256.Substring(0,8),RegisteredSha256=target.CoverSourceSha256,ResourceId=target.Id};Require(UpdateOfficialName(version,target)&&version.Name==target.Name+" · "+target.CoverSourceSha256.Substring(0,8),"Version suffix lost");
  Require(OfficialNames.Clean("  名称\r\n 测试  ")=="名称 测试"&&OfficialNames.Clean("坏\u0001名称")==null&&OfficialNames.Clean("截断…")==null&&OfficialNames.Clean(new string('名',121))==null,"Name sanitization");
  Common.SaveNew(Path.Combine(Common.Root,"evidence/name-existing-rules.json"),new{placeholder=placeholder,custom=custom,version=version,currentActualFourCards=library.Doc.Items,meaningfulPreserved=true,sanitizationPassed=true,noResourceChange=true});
  if(mode=="layout"){Common.SaveNew(Path.Combine(Common.Root,"evidence/name-layout-passed.json"),new{cards=4,named=found.Where(x=>x.NameSource!=null).Select(x=>new{id=x.Id,name=x.Name,source=x.NameSource}).ToArray(),autoPlayed=false,autoImported=false,method="internal TEST_BUILD handlers, not user clicks"});Close();return;}
  var receipt=await ImportJob("copy",target,null);bool duplicate;var item=RegisterImport(importOperation,receipt,out duplicate);Require(!duplicate&&item.Name==target.Name&&item.NameSource!=null&&item.RegisteredSha256==target.CoverSourceSha256&&item.PreviewConfirmedSha256==null&&item.DesktopConfirmedSha256==null,"Real named import");item.Name="本地壁纸 394944";item.NameSource=null;library.Save();ApplyOfficialNames(found);Require(item.Name==target.Name&&item.NameSource!=null,"Existing registered placeholder pipeline");SelectWallpaper(item);ClientShot(this,"name-imported-card");Common.SaveNew(Path.Combine(Common.Root,"evidence/name-import-passed.json"),new{item=item,receipt=receipt,autoPlayed=CurrentRun!=null,method="isolated internal import handler"});
  string cfg=Path.Combine(Common.Root,"tests/name-cache-root.txt"),missing=Path.Combine(Common.Root,"tests/no-name-cache");Directory.CreateDirectory(missing);File.WriteAllText(cfg,missing);var empty=await ImportJob("scan",null,null);var noName=CoverCandidates(empty).Single(x=>x.Id=="394944");Require(noName.Name=="本地壁纸 394944"&&noName.NameSource==null&&noName.Cover!=null,"Missing-name fallback harmed cover");Require(item.Name==target.Name,"Imported persistent name depends on cache");
  File.WriteAllText(Path.Combine(missing,"index"),"invalid private name-cache fixture");var damaged=await ImportJob("scan",null,null);Require(CoverCandidates(damaged).Single(x=>x.Id=="394944").NameSource==null,"Corrupt index accepted");
  File.WriteAllText(cfg,Path.Combine(Common.Root,"tests/synthetic-cache"));var synthetic=OfficialNames.ReadNames(new[]{"394944","335759","395417","366396"},()=>{});Require(synthetic.ContainsKey("394944")&&synthetic["394944"].Name.Length==100&&!synthetic.ContainsKey("335759"),"Long name or invalid title parsing");Require(!synthetic.ContainsKey("395417"),"Conflicting ID title accepted");Require(synthetic.ContainsKey("366396")&&synthetic["366396"].Name==synthetic["394944"].Name,"Same name different IDs lost");
  OpenLocalImport();await Task.Delay(400);await WaitCoverDialog();foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="394944"){Require(((ImportCandidate)row.Tag).Name.Length==100,"Long candidate pipeline");row.Selected=true;row.EnsureVisible();break;}importDialog.Size=importDialog.MinimumSize;await Task.Delay(100);foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="394944")row.EnsureVisible();ClientShot(importDialog,"name-long-fixture");importDialog.Close();
  bool cancelled=false;try{OfficialNames.ReadNames(new[]{"394944"},()=>{throw new OperationCanceledException();});}catch(OperationCanceledException){cancelled=true;}Require(cancelled,"Cancellation swallowed");
  File.WriteAllText(cfg,missing);foreach(string map in Directory.GetFiles(Path.Combine(Common.Root,"data/cover-cache/sources")))File.Delete(map);var task=ImportJob("scan",null,null,40);await Task.Delay(150);importOperation.Cancel();cancelled=false;try{await task;}catch(OperationCanceledException){cancelled=true;}Require(cancelled&&!importOperation.Busy&&!Directory.Exists(Path.Combine(importOperation.Folder,"cover-temp"))&&CurrentRun==null,"Task cancel cleanup");
  Common.SaveNew(Path.Combine(Common.Root,"evidence/name-negative-passed.json"),new{missingFallback=true,corruptFallback=true,malformedResponseIsolated=true,longNameBounded=true,truncatedAndControlTitlesRejected=true,conflictingIdRejected=true,sameNameDifferentIdsPreserved=true,cancelPropagated=true,taskCancelClean=true,importedNamePersistsWithoutOfficialCache=true,noPlayer=true});Close();
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/name-smoke-failed.json"),new{error=ex.ToString()});Write("name-smoke-failed",new{error=ex.ToString()});Close();}}
}
#endif
